"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[102],{9102:(e,t,i)=>{i.r(t),i.d(t,{PAPERS:()=>a});let a=[{id:"2610.26802",title:"Scaling Parameter-Efficient Fine-Tuning for Brain Encoding",up:231,href:"https://arxiv.org/abs/2610.26802",abstract:"Brain encoding models aim to predict neural responses to stimuli. The most widely used approach fits readouts from frozen pretrained backbones. Using neural data to train large models from scratch or fully fine-tune them after task-pretraining has proven difficult because neural data is costly and limited. We show that parameter-efficient fine-tuning (PEFT) enables us to effectively adapt very large pretrained backbones for brain encoding with a small number of trainable parameters. To make it computationally practical, we exploit the backbone's causal structure to predict multiple timepoints ",pdfUrl:"https://arxiv.org/pdf/2610.26802",primaryCategory:"cs.LG",published:"2026-10-19T00:00:00Z"},{id:"2610.26825",title:"MemT-1.0: Towards Memory-Native Evolution",up:146,href:"https://arxiv.org/abs/2610.26825",abstract:"Memory-native evolution requires making memory an intrinsic capability of foundation models, enabling them to continuously accumulate and utilize information. To this end, we introduce MemT-1.0, a new architecture of memory foundation models that internalize memory as part of model computation. Building on Metis, MemT-1.0 employs Gated DeltaNet-2 with a stable token-level memory update mechanism within each turn. We further introduce Mixture-of-Storage to scale native memory capacity. Following a deliberate backbone preparation, we develop a two-stage training pipeline consisting of continued ",pdfUrl:"https://arxiv.org/pdf/2610.26825",primaryCategory:"cs.CL",published:"2026-10-19T00:00:00Z"},{id:"2610.26549",title:"Holi-World: Building Holistic World Intelligence from Human-Ego Experience",up:109,href:"https://arxiv.org/abs/2610.26549",abstract:"Human egocentric experience offers a rich foundation for learning how the world is organized and how it changes through interaction. Realizing this potential at scale requires turning growing volumes of recordings into learning resources that connect scene structure, object semantics, and interaction histories across viewpoints and time, while reducing dependence on costly manual annotation. We introduce HOLI-WORLD, an integrated ecosystem connecting experience capture, world representation, automated data construction, model learning, and independent evaluation. To sup- port learning at scale",pdfUrl:"https://arxiv.org/pdf/2610.26549",primaryCategory:"cs.CV",published:"2026-10-19T00:00:00Z"},{id:"2610.25736",title:"Learning from Fleet Experience: A Collective Learning Paradigm for Robots",up:107,href:"https://arxiv.org/abs/2610.25736",abstract:"Experience generated during deployment offers an opportunity for robots to improve policy reliability through learning from their own executions. However, learning through human corrections requires teleoperators to monitor execution and intervene when policies fail, a demand that is difficult to meet as robot fleets grow. We introduce collective experience learning (CEL), a learning paradigm in which deployed robots share their execution experience to improve a common policy. We realize CEL through failure-guided experience retrieval fine-tuning (FERT), which uses failure contexts from robot ",pdfUrl:"https://arxiv.org/pdf/2610.25736",primaryCategory:"cs.RO",published:"2026-10-19T00:00:00Z"},{id:"2610.26824",title:"SpecMRL: Redesign Matryoshka Representation Learning within Parametric Spectrum",up:81,href:"https://arxiv.org/abs/2610.26824",abstract:"Matryoshka Representation Learning (MRL) is designed to support flexible representation sizes by jointly optimizing nested prefixes. While effective, this design lacks an explicit constraint to ensure that the leading portion provides a suitable compact encoding. To address this, we propose SpecMRL, which reorganizes the feature space to enable more effective prefix readout. Specifically, we extend MRL with a parameter-derived spectral basis organized with feature importance. SpecMRL otherwise follows standard MRL, with prefix readout performed in the learned spectral space. Experiments on MTE",pdfUrl:"https://arxiv.org/pdf/2610.26824",primaryCategory:"cs.CL",published:"2026-10-19T00:00:00Z"},{id:"2610.26834",title:"Kronecker Delta Rule for Long Context Linear Attention",up:28,href:"https://arxiv.org/abs/2610.26834",abstract:"We propose KronLSTM, a linear attention architecture based on the Kronecker Delta Rule, a novel update rule for associative matrix memories. KronLSTM extends the xLSTM family with a memory-revision mechanism that corrects targeted associations while modifying the memory only along a single direction in matrix space. This minimally invasive memory revision reduces interference with previously stored information compared with delta-rule updates, making it particularly well suited for long-context language modeling. The resulting memory dynamics can be mathematically described as a Markov chain t",pdfUrl:"https://arxiv.org/pdf/2610.26834",primaryCategory:"cs.LG",published:"2026-10-19T00:00:00Z"},{id:"2610.25950",title:"AdaExploreBench: Benchmarking LLM Agents for Proactive Exploration and Test-time Adaptation in Evolving Environments",up:27,href:"https://arxiv.org/abs/2610.25950",abstract:"Large Language Model (LLM) agents are increasingly deployed in unfamiliar and evolving environments, requiring them to proactively explore, understand, and adapt to environmental dynamics. However, existing benchmarks rarely test whether agents can proactively discover how an environment works and adapt as it evolves. To address this gap, we introduce AdaExploreBench, a benchmark for proactive exploration and test-time adaptation in evolving environments. By instantiating environmental dynamics as hidden rules, AdaExploreBench requires agents to actively acquire evidence and infer the rules. U",pdfUrl:"https://arxiv.org/pdf/2610.25950",primaryCategory:"cs.CL",crossrefDoi:"https://doi.org/10.1145/3711896.3736570",year:2025,openalexId:"https://openalex.org/W4412877164",published:"2026-10-19T00:00:00Z",crossrefIssued:"2025-08-03"},{id:"2610.06830",title:"MemPilot: Orchestrating On-Demand Multimodal Memory Curation for LLM Agents",up:25,href:"https://arxiv.org/abs/2610.06830",abstract:"Memory has become integral to the LLM agent ecosystem, supporting information retention and reuse across interactions. However, most existing agent memory systems construct memory in a query-agnostic manner, which can incur unnecessary preprocessing cost and discard details that later prove essential. Recent studies have begun shifting memory processing toward runtime adaptation, but typically specialize in particular operations or fixed processing schemes, leaving flexible control over performance, cost, and latency largely underexplored. To address this challenge, we present \\textbf{MemPilot",pdfUrl:"https://arxiv.org/pdf/2610.06830",primaryCategory:"cs.CL",doi:"https://doi.org/10.52202/085713-0593",year:2025,openalexId:"https://openalex.org/W4407759090",published:"2026-10-05T00:00:00Z"},{id:"2610.26853",title:"InfiniDream: Open-Ended Photorealistic 3D Worlds Through Procedural Generation",up:25,href:"https://arxiv.org/abs/2610.26853",abstract:"Procedural generation plays a key role in synthetic data creation and game development, offering greater controllability, editability, and diversity than static mesh representations. However, VLM-based code generation often produces relatively simple 3D assets, while sophisticated photorealistic procedural systems require extensive manual development. Existing VLM-guided procedural methods remain largely constrained by predefined factories and APIs, limiting their ability to create novel asset types. We introduce InfiniDream, a VLM-driven framework for open-ended procedural 3D world generation",pdfUrl:"https://arxiv.org/pdf/2610.26853",primaryCategory:"cs.CV",published:"2026-10-19T00:00:00Z"},{id:"2610.26663",title:"RoboValue: A Fine-Grained Sim-and-Real Benchmark for Unified Evaluation of Robotic Value Models",up:23,href:"https://arxiv.org/abs/2610.26663",abstract:"Robotic value models assess task execution from visual observations and instructions, providing feedback for policy learning and execution monitoring. However, existing evaluations cover only selected aspects of execution understanding, leaving the reliability of value feedback insufficiently tested. We introduce RoboValue, a fine-grained sim-and-real benchmark for unified evaluation of robotic value models. Its framework evaluates four complementary capability dimensions through shared interfaces: task-state understanding, temporal progress monitoring, failure and recovery reasoning, and valu",pdfUrl:"https://arxiv.org/pdf/2610.26663",primaryCategory:"cs.RO",published:"2026-10-19T00:00:00Z"},{id:"2610.26851",title:"Manga2Animate: An Agentic Framework for Faithful Manga Animation with Script and Storyboard Planning",up:23,href:"https://arxiv.org/abs/2610.26851",abstract:"Adapting existing manga into coherent animation that stays faithful to the source is a valuable yet challenging task. Existing methods either access the manga mainly through text, losing its characters and art style, or feed manga pages directly into video generation models, which misinterpret the manga's structure and produce incorrect storylines. In this paper, we propose Manga2Animate, a multi-agent framework that grounds every stage of generation in the source manga. We decompose the task into two intermediate representations, an animation script and a visual storyboard. Each representatio",pdfUrl:"https://arxiv.org/pdf/2610.26851",primaryCategory:"cs.CV",published:"2026-10-19T00:00:00Z"},{id:"2610.23986",title:"BlenderWorld: Benchmarking Visual Agents for 3D Creation from Real-World References",up:21,href:"https://arxiv.org/abs/2610.23986",abstract:"Recent advances in multimodal large language models (MLLMs) have enabled them to act as autonomous agents, creating and editing 3D models via code or direct software manipulation. In practical workflows, these models must infer object shapes, materials, spatial layouts, and lighting from diverse references while strictly following instructions to reconstruct, modify, or design 3D content. However, existing benchmarks provide limited coverage of such open-ended requests across real-world scenarios. To bridge this gap, we introduce BlenderWorld, the first comprehensive benchmark dedicated to eva",pdfUrl:"https://arxiv.org/pdf/2610.23986",primaryCategory:"cs.CV",published:"2026-10-14T00:00:00Z"},{id:"2609.22332",title:"AffordanceWAM: Affordance-Aware Joint World-Action Modeling for Robot Manipulation",up:17,href:"https://arxiv.org/abs/2609.22332",abstract:"Generalizable robot manipulation requires predicting how a scene will evolve, identifying where interactions are feasible, and determining how to act. Action-labeled robot videos directly supervise control but are costly and limited in diversity, whereas egocentric human videos capture diverse interactions but lack robot actions and differ in embodiment and appearance. We introduce AffordanceWAM, an affordance-aware generative World Action Model that represents object-centric spatiotemporal affordance through Scalar Affordance and Affordance Heatmap, within the generated future World. This rep",pdfUrl:"https://arxiv.org/pdf/2609.22332",primaryCategory:"cs.RO",published:"2026-10-18T00:00:00Z"},{id:"2610.25011",title:"FineSplat: Fine Patches, Local Groups, Detailed Splats",up:17,href:"https://arxiv.org/abs/2610.25011",abstract:"Feed-forward 3D Gaussian Splatting (3DGS) promises instant scene reconstruction with high-quality novel-view synthesis. Yet, fine-grained geometry and appearance remain difficult to recover, motivating us to revisit how feed-forward models represent, aggregate, and refine detailed visual information. We introduce FineSplat, a feed-forward 3DGS framework built around fine-grained image patches. Since global multi-view attention becomes prohibitively expensive at such high token resolutions, we develop a dual-grouping strategy that combines two complementary forms of locality: view-wise grouping",pdfUrl:"https://arxiv.org/pdf/2610.25011",primaryCategory:"cs.CV",published:"2026-10-18T00:00:00Z"},{id:"2610.17724",title:"Evidence-First Agentic Verification",up:16,href:"https://arxiv.org/abs/2610.17724",abstract:"Long-horizon, semi-verifiable agentic tasks often rely on rubric-based evaluation, but the evidence needed to assess these tasks can be spread across the environment state and the execution trace. A judge may overlook this evidence or accept unsupported claims, including an agent's own reports of success. When rubric verdicts serve as reinforcement-learning rewards, such errors can reinforce undesirable behavior. We introduce Sauron, an evidence-first agentic verifier that investigates both state and trace and relies on a claim only after independently validating it against its source. Bounded",pdfUrl:"https://arxiv.org/pdf/2610.17724",primaryCategory:"cs.AI",published:"2026-10-13T00:00:00Z"},{id:"2610.26848",title:"Where is Physical RSI capability from? An Observational Scaling Law of LLM-as-policy",up:16,href:"https://arxiv.org/abs/2610.26848",abstract:"In this paper, we systematically investigate the mechanisms, scaling behavior, and generalization of physical Recursive self-improvement. We introduce PhysRSI-eval to quantify physical RSI through a five-axis metric: First-Attempt Performance, Efficiency, Success, Budget and Improvement from failure. Different VLMs are evaluated on 18 manipulation tasks under a fixed interaction budget. The analysis of experimental results motivates the Physical Barrel Hypothesis: different capabilities may constrain different parts of improvement. The five-axis metrics also distinguish systems with close publ",pdfUrl:"https://arxiv.org/pdf/2610.26848",primaryCategory:"cs.RO",published:"2026-10-19T00:00:00Z"},{id:"2610.26811",title:"State World Models: Execute the Rules, Generate the Pixels",up:12,href:"https://arxiv.org/abs/2610.26811",abstract:"Existing world models can generate action-conditioned video from a single image. Many focus on camera movement, allowing users to explore the generated scene. However, navigation alone does not ensure that an action follows persistent rules when its outcome depends on state that is invisible in the current frame. We present Stateful Harness, a framework that separates world evolution from video rendering to support stateful and rule-governed interaction. It maintains an evolving world state under specified rules, renders each resulting event with a frozen video model, and uses the generated cl",pdfUrl:"https://arxiv.org/pdf/2610.26811",primaryCategory:"cs.CV",published:"2026-10-19T00:00:00Z"},{id:"2606.31876",title:"Harnessing Textual Refusal Directions for Multimodal Safety",up:11,href:"https://arxiv.org/abs/2606.31876",abstract:"Safety in Multimodal Large Language Models (MLLMs) depends on unsafe multimodal data for post-training alignment or activation steering. However, such data is hard to collect, must be gathered anew for each modality, and its collection and distribution raise ethical and legal concerns. In this work, we relax this constraint and investigate whether textual refusal directions, extracted directly from the LLM backbone, generalize across modalities (i.e., image, video). Preliminary findings confirm this ability, though effectiveness is conditioned by layer selection, steering strength, and cross-m",pdfUrl:"https://arxiv.org/pdf/2606.31876",primaryCategory:"cs.AI",published:"2026-10-16T00:00:00Z"},{id:"2610.22328",title:"ACEdit: Stable Multi-Turn Image Editing via Asymmetric Conditioning",up:11,href:"https://arxiv.org/abs/2610.22328",abstract:"Image editing models produce impressive results for individual edits, but their quality often deteriorates over multiple editing turns. Each editing turn introduces small distribution shifts that accumulate over successive edits, creating a gap between the input distributions encountered during the editor's original training and multi-turn inference. We introduce a training scheme that makes multi-turn image editing stable under this accumulating distribution shift. A key is to force the editor to operate on its own outputs from previous editing turns during training, bringing the principle of",pdfUrl:"https://arxiv.org/pdf/2610.22328",primaryCategory:"cs.CV",published:"2026-10-15T00:00:00Z"},{id:"2610.16782",title:"LIBERO-Industry: Benchmarking Robotic Manipulation under Industrial Process Constraints",up:10,href:"https://arxiv.org/abs/2610.16782",abstract:"Industrial manipulation in flexible manufacturing, e.g., high-mix, low-volume (HMLV) electronics assembly, requires robot policies to adapt to changing products and production conditions. Such settings impose industrial process constraints, including product variants, moving material flows, finite execution windows, and tight geometric tolerances. However, existing evaluation frameworks do not systematically capture these constraints when assessing generalist robot policies. To address this gap, we introduce LIBERO-Industry, a novel benchmark built on the widely used robot learning benchmark L",pdfUrl:"https://arxiv.org/pdf/2610.16782",primaryCategory:"cs.AI",published:"2026-10-15T00:00:00Z"},{id:"2610.24766",title:"ECHO: Efficient Causal Self-Recursion Beyond Auxiliary Multi-Token Prediction",up:8,href:"https://arxiv.org/abs/2610.24766",abstract:"Existing Multi-token prediction (MTP) methods are auxiliary by design: the multi-horizon loss mostly trains modules attached to the backbone, and each added horizon costs another module and another pass. We propose Efficient Causal Self-Recursion (ECHO), which removes both costs. The backbone's own final layer predicts every horizon, so the supervision lands on the parameters that generate the next token, and Dynamic Depth Sampling (DDS) keeps deeper horizons affordable by drawing the training depth with probabilities that decay along depth. Future prediction thus becomes part of the autoregre",pdfUrl:"https://arxiv.org/pdf/2610.24766",primaryCategory:"cs.CL",published:"2026-10-17T00:00:00Z"},{id:"2610.24133",title:"A Conditional No-Hair Theorem for Transformers: How Language Models Forget Their Prompt",up:7,href:"https://arxiv.org/abs/2610.24133",abstract:"We ask how much an autoregressive transformer retains of its prompt after generating $t$ tokens. Consider two different prompts followed by the same continuation text, so that any difference in their hidden states comes from the prompt alone, and we find that the distance between their hidden states decays approximately as a power law $t^{-α}$, where $α=1$ is the rate at which a fixed prompt's share of uniform attention shrinks and smaller values mean longer memory. Trained models forget fast ($α\\approx0.55$--$0.7$), untrained ones slowly ($α\\approx0.2$--$0.5$). We prove that this offset is $O",pdfUrl:"https://arxiv.org/pdf/2610.24133",primaryCategory:"cs.AI",published:"2026-10-16T00:00:00Z"},{id:"2610.24791",title:"UniAVC: Unified Audio-Video Creation via Progressive Training and Asymmetric Scheduling",up:7,href:"https://arxiv.org/abs/2610.24791",abstract:"Unified audio-video creation requires a single model capable of text-conditioned joint synthesis, bidirectional cross-modal generation, and instruction-guided editing across both modalities. Existing methods rely heavily on paired corpora, which are scarce for joint generation and even rarer for editing. Consequently, they are spent learning single-branch generative and editing capabilities that abundant unimodal data could readily teach, rather than on the cross-modal coupling. Furthermore, prevailing systems apply a single shared noise schedule to both modalities, neglecting two critical lim",pdfUrl:"https://arxiv.org/pdf/2610.24791",primaryCategory:"cs.CV",published:"2026-10-17T00:00:00Z"},{id:"2610.25060",title:'Policy Is Not Capability: Some Safety Benchmarks Measure Which Definition of "Unsafe" You Trained On',up:7,href:"https://arxiv.org/abs/2610.25060",abstract:'A guardrail classifier is reported as if unsafe were a property of text. It is not: it is a property of a policy, and the policy enters the model through its labels. We exploit an accident of an industrial deployment in which the same ~53k prompts were labelled twice, under two operational definitions ("is this a request for harmful content?" and "would a moderator block this?"), and used to train ten guardrail arms sharing architecture, codebase and optimiser family, at two model scales. First, the guardrail\'s own training corpus already contained the benchmarks: JailbreakBench-benign is 88% ',pdfUrl:"https://arxiv.org/pdf/2610.25060",primaryCategory:"cs.LG",published:"2026-10-18T00:00:00Z"},{id:"W4393160747",title:"ExpeL: LLM Agents Are Experiential Learners",up:0,href:"https://doi.org/10.1609/aaai.v38i17.29936",doi:"https://doi.org/10.1609/aaai.v38i17.29936",year:2024,openalexId:"https://openalex.org/W4393160747"},{id:"W4391620956",title:"Understanding the planning of LLM agents: A survey",up:0,href:"https://doi.org/10.48550/arxiv.2402.02716",doi:"https://doi.org/10.48550/arxiv.2402.02716",year:2024,openalexId:"https://openalex.org/W4391620956"},{id:"W7167900302",title:"LLM Agents Factory: Retrieval of Domain-Specific LLM Agents",up:0,href:"https://doi.org/10.1145/3805712.3808515",doi:"https://doi.org/10.1145/3805712.3808515",year:2026,openalexId:"https://openalex.org/W7167900302"}]}}]);